/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { MatrixSymbol, Rational, Sym, integral, kindOf } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.matrices.kind", () => {
  it("A.kind", () => {
    expect(sympyStr(kindOf(new MatrixSymbol('A', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n }))))).toBe('MatrixKind(NumberKind)');
  });
  it("intM.kind", () => {
    const x = new Sym('x');
    expect(sympyStr(kindOf(integral(new MatrixSymbol('A', Rational.of(2n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n })), [x])))).toBe('MatrixKind(NumberKind)');
  });
});
